	["A one-time reminder moves to the archive once it has fired or you mark it done."] = "一次性提醒在觸發或你標記完成後移入存檔。",
	["A page of My Adventure"] = "我的冒險的一頁",
	["A pin on the world map for each giver of the quests left in the zone the map shows. Hover it for the quests, click it for a waypoint. The map's EldoUI pin switch hides it with the other pins."] = "在世界地圖上為地圖所示區域中剩餘任務的每個發布者放一個標記。懸停檢視任務，點選設定路徑點。地圖上的EldoUI標記開關會把它和其他標記一起隱藏。",
	["A pin where the next step of each attunement you are on starts. Click it for the arrow."] = "在你進行中的每個進入資格的下一步起點放一個標記。點選它顯示箭頭。",
	["A place in your journal"] = "日誌中的一個地點",
	["a place to find"] = "一個待尋找的地點",
	["a profession you do not have"] = "你沒有的專業",
	["a quest"] = "一個任務",
	["A quest counts once you both have it and one of its objectives moves forward while you are grouped."] = "當你們都有該任務，並且組隊時它的一個目標有進展，就會計入。",
	["A quest of this event."] = "此活動的一個任務。",
	["A quest outside dungeons, or a creature and what it drops."] = "地城以外的任務，或一個生物及其掉落。",
	["A quest that needs this standing."] = "需要此聲望的任務。",
	["A quest that rewards the recipe."] = "獎勵此配方的任務。",
	["a racial spell; not modeled"] = "種族法術；不模擬",
	["a raid"] = "一個團隊副本",
	["A reached goal moves to the archive instead of staying in the Reached list."] = "達成的目標移入存檔，而不是留在已達成列表中。",
	["A reminder"] = "提醒",
	["A sample step"] = "示例步驟",
	["A scroll above the name."] = "名字上方的卷軸。",
	["A scroll in a bronze frame above the name, to match the WoW Forever art style."] = "名字上方帶青銅邊框的卷軸，與WoW Forever的美術風格一致。",
	["A scroll, the quest giver's exclamation mark, a dot in your accent color, a scroll in a bronze frame, or a yellow square with a mark that reads for every kind of color blindness."] = "卷軸、任務發布者的感嘆號、強調色的圓點、帶青銅邊框的卷軸，或帶標記、任何色盲類型都能辨認的黃色方塊。",
	["A short card when you enter a zone or a dungeon: your quests there, rares, your notes and your last run. Off in combat."] = "進入地區或地城時的簡短卡片：你在那裡的任務、稀有怪、你的筆記和你上次的進度。戰鬥中關閉。",
	["A short summary of the session during the logout countdown, also kept as a row in the Day view."] = "在登出倒計時期間顯示本次遊戲的簡短總結，也會作為一行儲存在日檢視中。",
	["A short tour of My Adventure."] = "我的冒險簡短導覽。",
	["A small dot in your accent color left of the bar."] = "血條左側一個強調色的小圓點。",
	["A small icon on the nameplate of a creature that can drop a quest starter. Needs EldoUI's Nameplates module."] = "在可能掉落任務起始物品的生物的姓名板上顯示一個小圖示。需要EldoUI的Nameplates模組。",
	["A small mark after each sentence; hover it to see the facts the sentence comes from."] = "每句話後的小標記；滑鼠懸停可檢視該句所依據的事實。",
	["A solid dark page with no ornaments, numbers first."] = "純深色頁面，無裝飾，數字優先。",
	["a spell"] = "一個法術",
	["A step of %s is here: %s."] = "%s的一個步驟在這裡：%s。",
	["A step of %s is inside: %s."] = "%s的一個步驟在內部：%s。",
	["A string with this character's Best in Slot, plan sets, spec and talents (no name or realm) to share."] = "包含此角色的Best in Slot、計劃套裝、專精和天賦（不含名字和伺服器）的分享字串。",
	["A strip over the chapters with a mark for each level and its big moments. Click a level to open its chapter. Shown in the level view while no search or filter is on."] = "章節上方的一條時間帶，標記每個等級及其重要時刻。點選一個等級開啟該章。在等級檢視中且沒有搜尋或過濾時顯示。",
	["A to-do you check off yourself."] = "你自己勾選的待辦事項。",
	["A toast or banner, a sound and a chat line when a wished item is in a loot window or a roll, or drops in the dungeon you enter. Set them in /eui > Loot Guide."] = "當願望清單物品出現在拾取視窗或擲骰中，或在你進入的地城中掉落時，顯示通知或橫幅、播放聲音併傳送一行聊天資訊。在/eui > Loot Guide中設定。",
	["A toast when you finish a step or a whole attunement. Nothing is posted to chat."] = "完成一個步驟或整個進入資格時顯示通知。不會傳送到聊天。",
	["A trainer who teaches this recipe."] = "教授此配方的訓練師。",
	["A vendor during this event."] = "此活動期間的商人。",
	["A vendor for these rewards."] = "出售這些獎勵的商人。",
	["A vendor who sells the recipe."] = "出售此配方的商人。",
	["A yellow square with a mark above the name; the shape carries it too."] = "名字上方帶標記的黃色方塊；形狀本身也能區分。",
	["A zone, or a spot inside one like Frostmane Hold."] = "一個地區，或其中的一個地點，比如霜鬃巨魔要塞。",
	["Abandoned"] = "已放棄",
	["Abandoned quests"] = "已放棄的任務",
	["Abandoned, failed, or removed by the game. The journal only lists them; nothing is picked up again for you."] = "已放棄、失敗或被遊戲移除。日誌只列出它們；不會替你重新接取。",
	["About %s of play at your recent pace. It counts your own last levels only."] = "按你最近的速度大約需要%s遊戲時間。只計算你自己最近的等級。",
	["About %s per kill."] = "每次擊殺約%s。",
