	["About this zone"] = "關於此地區",
	["Above the name"] = "名字上方",
	["Accept merges it into this character's journal: nothing is lost, and a backup is taken first."] = "接受會將其合併到此角色的日誌中：不會丟失任何內容，並會先做備份。",
