	["Added %s to %s."] = "已將%s加入%s。",
	["Adds a button to the toast that posts one line in guild chat when you click it."] = "為通知新增一個按鈕，點選後在公會聊天中傳送一行。",
	["Adds a Need, Greed or Pass word to that box. It is a label only and never rolls for you."] = "為該框新增需求、貪婪或放棄字樣。只是一個標籤，絕不會替你擲骰。",
	["Adds a Quests line (done of total) to Zone Info's world map tooltip when you hover a zone. Needs the Zone Info module."] = "懸停區域時，在Zone Info的世界地圖滑鼠提示中新增一行任務（已完成/總數）。需要Zone Info模組。",
	["Adds it to your goals, so the tracker and the Goals page follow it."] = "將它加入你的目標，讓追蹤器和目標頁跟進它。",
	["Adds the best-in-slot items for your spec that you do not own and have not wished for yet."] = "新增你專精中你尚未擁有且尚未許願的Best in Slot物品。",
	["Adds the item to your active wishlist, or takes it off every list on show."] = "將物品加入你當前的願望清單，或從所有顯示的列表中移除。",
	["Adds the item to your active wishlist, or takes it off."] = "將物品加入你當前的願望清單，或將其移除。",
