	["Estimates from fights against a target dummy with your own character sheet and public Classic combat rules. Set bonuses and item procs are not counted."] = "用你自己的角色屬性和公開的經典舊世戰鬥規則對訓練假人戰鬥得出的估計。不計算套裝獎勵和物品觸發效果。",
	["Everlook"] = "永望鎮",
	["Every attunement and key step by step. Its next steps show up in Next trips and on Today."] = "逐步顯示每個進入資格和鑰匙。其下一步會出現在下次旅程和今日中。",
	["Every attunement and key, step by step."] = "每個進入資格和鑰匙，逐步顯示。",
	["Every best-in-slot item is already yours or on your wishlist."] = "每件Best in Slot物品都已是你的或在你的願望清單上。",
	["Every craft per profession: what it makes, the skill it needs, the reagents you own and where the recipe comes from."] = "每個專業的所有制造：製造什麼、所需技能、你擁有的材料和配方來源。",
	["Every dungeon and raid with its bosses, loot, drop chances and quests. Inside a dungeon the window opens on it."] = "每個地城和團隊副本的首領、掉落、掉落機率和任務。在地城內時，視窗會開啟到該地城。",
	["Every dungeon and raid: bosses, drops with chances, quests and what is an upgrade for you."] = "每個地城和團隊副本：首領、帶機率的掉落、任務以及對你來說是升級的物品。",
	["Every flight master you speak to adds a flight path. These zones fit your level:"] = "每與一位飛行管理員交談就會增加一條飛行路線。以下地區適合你的等級：",
	["Every idea for where to go next, with filters."] = "關於下一步去哪裡的所有點子，可過濾。",
	["Every idea, best first, with filters for dungeons, quests, attunements, and zones, for your group and the time you have. Hover a card to see every reason; Not now puts it away until your next level."] = "所有點子，最好的在前，可按地城、任務、進入資格和地區過濾，適合你的隊伍和你的時間。滑鼠懸停卡片檢視所有原因；“以後再說”會把它收起直到你下次升級。",
	["Every item, creature, quest and place in sortable tables with filters and a detail panel."] = "所有物品、生物、任務和地點，以可排序的表格顯示，帶過濾和詳情面板。",
	["Every item, mob, quest and vendor the loot data knows, with filters and sorting."] = "掉落資料中的所有物品、怪物、任務和商人，可過濾和排序。",
	["Every keepsake, grouped by kind."] = "所有紀念，按類型分組。",
	["Every kind of result."] = "所有類型的結果。",
	["Every level is behind you"] = "所有等級都已走過",
	["Every level is behind you. The journal keeps writing down your runs, finds, and standings."] = "所有等級都已走過。日誌會繼續記錄你的進度、發現和聲望。",
	["Every login"] = "每次登入",
	["Every Loot Guide page is switched off. Turn pages on in /eui > Loot Guide."] = "Loot Guide的所有頁面都已關閉。在/eui > Loot Guide中開啟頁面。",
	["Every moment."] = "每個時刻。",
	["Every new standing"] = "每個新的聲望等級",
	["Every new standing, or Honored and up only. Changing it on a preset turns it into Custom."] = "每個新的聲望等級，或僅尊敬及以上。在預設上更改會使其變為自定義。",
	["Every part and chapter of the Book. Click one to turn to it."] = "書中的每個部分和章節。點選一個即可翻到那裡。",
	["Every PvP reward with its cost and the rank or standing it needs, plus a planner for the weeks to afford them."] = "每個PvP獎勵及其花費和所需軍銜或聲望，以及攢夠它們所需週數的計劃器。",
	["Every quest you handed in since the journal began, with where, when, and what it gave."] = "日誌開始以來你交付的每個任務，包括地點、時間和獎勵。",
	["Every quest you handed in, with where, when, who gave it, and who came along; your quest log; and the quests the game remembers from before."] = "你交付的每個任務，包括地點、時間、發布者和同行者；你的任務日誌；以及遊戲記得的以前的任務。",
	["Every run the Instances module recorded."] = "副本模組記錄的每次進度。",
	["Every step for both sides and every class, also content the client does not list yet."] = "雙方陣營和每個職業的每一步，包括客戶端尚未列出的內容。",
	["Every suggestion, best first."] = "每條建議，最好的在前。",
	["Every time"] = "每次",
	["Every way to get one item."] = "獲得一件物品的所有途徑。",
	["Every zone"] = "每個地區",
	["Every zone you visited, with its corners, time, kills, and quests, and every dungeon with its runs."] = "你去過的每個地區，包括角落、時間、擊殺和任務，以及每個地城及其進度。",
	["Every zone's quests: how many you have done, what is left and who gives it, with a Map button for each giver."] = "每個區域的任務：你完成了多少、還剩什麼、由誰發布，每個發布者都有地圖按鈕。",
	["Everyone"] = "所有人",
	["Everyone falls sometime. There is no need to chase this one."] = "人總有倒下的時候。不必追著這個。",
	["Everyone falls sometime. There is no need to chase this one; here is what fits you instead:"] = "人總有倒下的時候。不必追著這個；這些更適合你：",
	["Everyone you grouped with."] = "所有與你組過隊的人。",
	["Everything"] = "全部",
	["Everything is selected. Press Ctrl+C and share it. It holds your gear plans, spec and talents, not your name or realm."] = "已全部選中。按Ctrl+C分享。其中包含你的裝備計劃、專精和天賦，不包含你的名字或伺服器。",
	["Everything is selected. Press Ctrl+C and share it. Others paste it into /eui import or the wishlist's Import."] = "已全部選中。按Ctrl+C分享。其他人將其貼上到/eui import或願望清單的匯入中。",
	["Everything reached. Start a new one with New goal."] = "全部達成。用新目標開始一個新的。",
	["Everything you can get at your level is already as good as what you wear."] = "你在當前等級能獲得的所有物品都已不比你身上的好。",
	["Everything, rare (blue) finds too, long chapters, every chapter open and a taller tracker."] = "全部，包括稀有（藍色）發現，長章節，所有章節展開，更高的追蹤器。",
