	["falls"] = "倒下",
	["Fanfare's \"Journal moment\" triggers play or show with each moment. While such a trigger, or a level-up or boss-kill trigger, has a sound, the moment plays none of its own, so you hear one sound."] = "Fanfare的“日誌時刻”觸發器會在每個時刻播放聲音或顯示內容。只要這樣的觸發器，或升級或擊殺首領的觸發器帶有聲音，時刻本身就不會播放聲音，這樣你只會聽到一個聲音。",
	["Farmed for %s"] = "刷了%s",
	["Fast (8 ms a frame)"] = "快速（每幀8毫秒）",
	["fastest"] = "最快",
	["Feet"] = "腳",
	["Fellowship"] = "同伴",
