	["Fiery Weapon"] = "烈焰武器",
	["Lifestealing"] = "生命偷取",
	["Fight"] = "戰鬥",
	["Fighting"] = "戰鬥中",
	["Fights against a target dummy with the best items of your list (one-minute fights, out of combat). Progress shows here, in the datatext and as a toast when done."] = "用你列表中最好的物品對訓練假人戰鬥（一分鐘戰鬥，非戰鬥狀態）。進度顯示在這裡、資訊文字中，完成時會彈出通知。",
	["Fights against a target dummy with the best items of your list per slot: a quick pass, exact runs of the top picks, then the best set (one-minute fights, out of combat)."] = "按欄位用你列表中最好的物品對訓練假人戰鬥：快速篩選、對最佳選擇精確模擬，然後是最佳套裝（一分鐘戰鬥，非戰鬥狀態）。",
	["Fights against a target dummy with this item instead of what you wear in its slot (about a second, out of combat). The result shows here, in the tooltip and as a toast."] = "用此物品代替你該欄位的裝備對訓練假人戰鬥（約一秒，非戰鬥狀態）。結果顯示在這裡、滑鼠提示中和通知中。",
	["Fights against a target dummy with your own character sheet. Slower, but counts how your talents and spells use each stat. Items not simulated yet keep the weights gain."] = "用你自己的角色屬性對訓練假人戰鬥。較慢，但會計算你的天賦和法術如何利用每種屬性。尚未模擬的物品保留權重收益。",
	["Fights against a target dummy with your own character sheet: DPS numbers for your gear, Best in Slot and plan sets. /eui sim opens its window."] = "用你自己的角色屬性對訓練假人戰鬥：你的裝備、Best in Slot和計劃套裝的DPS數值。/eui sim開啟其視窗。",
	["Fills an empty slot"] = "填補空欄位",
	["Fills the set with the Best in Slot items (the simulated set in Simulator mode)."] = "用Best in Slot物品填充套裝（模擬器模式下為模擬出的套裝）。",
	["Fills the set with your equipped gear."] = "用你當前的裝備填充套裝。",
