	["Pins at dungeon and raid entrances on the world and zone maps, with the level range and your upgrades inside. Where the game draws its own entrance pin, ours steps aside, so no entrance shows twice."] = "在世界地圖和區域地圖上的地城與團隊副本入口處顯示標記，附帶等級範圍和其中對你的提升。在遊戲自己顯示入口標記的位置，我們的標記會自動隱藏，避免同一入口出現兩次。",
	["Pins for the givers of quests you can pick up now."] = "為你現在可接任務的發布者放置標記。",
	["Pins the biggest of %d camps on your map. Click again for the next one; after the last the pin goes away."] = { other = "在你的地圖上標記%d個營地中最大的一個。再次點選標記下一個；最後一個之後標記消失。" },
	["Pins the dungeon's entrance on your map."] = "在你的地圖上標記該地城的入口。",
	["Pins the entrance in %s on your map and turns on the arrow."] = "在你的地圖上標記%s的入口並開啟箭頭。",
	["Pins the entrance on your map and opens the map there (out of combat)."] = "在你的地圖上標記入口並在那裡開啟地圖（非戰鬥中）。",
	["Pins the entrance on your map."] = "在你的地圖上標記入口。",
	["Pins the instance entrance on your map and turns on the arrow."] = "在你的地圖上標記副本入口並開啟箭頭。",
	["Pins the instance entrance on your map, turns on the arrow and opens the map there (out of combat)."] = "在你的地圖上標記副本入口，開啟箭頭並在那裡開啟地圖（非戰鬥中）。",
	["Pins the place on your map and turns on the arrow."] = "在你的地圖上標記該地點並開啟箭頭。",
	["Pins the place on your map and turns on the arrow. Click again to take the pin away."] = "在你的地圖上標記該地點並開啟箭頭。再次點選移除標記。",
	["Place"] = "地點",
	["Places"] = "地點",
	["Places the boss markers by where the creatures stand in the Classic data, on a plain grid. Approximate: walls and floors are not drawn."] = "根據經典舊世資料中生物所站的位置，在簡單網格上放置首領標記。僅為近似：不繪製牆壁和地面。",
	["Plan"] = "計劃",
	["Plan pieces to see the total and how many weeks of your recent honor each one takes."] = "規劃部件以檢視總計，以及每件需要你最近幾周多少周的榮譽。",
	["Plan set"] = "方案套裝",
