	["Player notes"] = "玩家備註",
	["Plays moment sounds on the Master channel."] = "在主聲道播放時刻音效。",
	["Plays with the toast for a finished attunement. Step toasts are silent."] = "隨完成進入資格的提示一起播放。步驟提示無聲。",
	["Plays with this kind of moment. None: the card stays quiet."] = "隨這類時刻播放。無：卡片保持安靜。",
