	["Poor"] = "粗糙",
	["Poor (gray)"] = "粗糙（灰色）",
	["Posts one line in guild chat."] = "在公會聊天中傳送一行。",
	["Press %s to take a screenshot. Click or press Esc to close."] = "按%s截圖。點選或按Esc關閉。",
	["Press Ctrl+C to copy it, save it as a .html file and open it in a browser. Print it to PDF for a keepsake."] = "按Ctrl+C複製，儲存為.html檔案並在瀏覽器中開啟。列印成PDF留作紀念。",
	["Press Ctrl+C to copy it, then paste it anywhere."] = "按Ctrl+C複製，然後貼上到任意位置。",
	["Press Ctrl+C to copy it, then paste it into any Markdown editor or note app."] = "按Ctrl+C複製，然後貼上到任意Markdown編輯器或筆記應用中。",
	["Press Ctrl+C to copy the code. Use \"Paste a journal code\" on this PC or another to restore the journal. Nothing is sent anywhere."] = "按Ctrl+C複製程式碼。在這臺或另一臺電腦上使用“貼上日誌程式碼”即可恢復日誌。不會傳送到任何地方。",
	["Press Ctrl+C to copy. Nothing is sent anywhere: paste it where you like."] = "按Ctrl+C複製。不會傳送到任何地方：貼上到你想要的地方。",
	["Press Ctrl+C to copy. Paste it back in with Paste a journal code, on this PC or another. Nothing is sent anywhere."] = "按Ctrl+C複製。在這臺或另一臺電腦上用“貼上日誌程式碼”貼回。不會傳送到任何地方。",
	["Press Sim to compare the checked sets in the same fights."] = "點選Sim，在相同的戰鬥中比較勾選的套裝。",
	["Press Sim to read your character and fight a target dummy 120 times. It takes a few seconds and runs out of combat."] = "點選Sim讀取你的角色並與訓練假人戰鬥120次。需要幾秒鐘，在非戰鬥中進行。",
	["Previews a code starting with !EUJ1!, FJ2: or FJ1:. A full backup can be merged or used to replace your journal. Recent changes are merged."] = "預覽以!EUJ1!、FJ2:或FJ1:開頭的程式碼。完整備份可與你的日誌合併或替換日誌。近期更改會合併到日誌中。",
	["Previous pages"] = "上一頁",
