	["Put on %s in %s"] = "裝備：%s，於%s",
	["Puts a group line into the chat box. Nothing is sent until you press Enter."] = "在聊天框中放入一行組隊資訊。按回車前不會傳送。",
	["Puts every journal the last import touched back as it was before, and its settings too."] = "將上次匯入影響的每份日誌恢復到之前的樣子，包括其設定。",
	["Puts every piece you do not have on your active wishlist."] = "將你沒有的每件部件放入當前願望清單。",
	["Puts its quests that are already in your log on the objective tracker. Nothing is accepted for you."] = "將其已在你任務日誌中的任務放到目標追蹤器上。不會替你接受任何任務。",
	["Puts one line about your character in the chat box. You read it and press Enter to send it."] = "在聊天框中放入一行關於你角色的介紹。你閱讀後按回車傳送。",
	["Puts the item in this plan set on the Best in Slot page, or takes it out. Plan sets are plans, not equipment sets."] = "將物品放入或移出Best in Slot頁面的此方案套裝。方案套裝只是計劃，不是裝備方案。",
	["Puts the item link into the chat line you are typing in."] = "將物品連結插入你正在輸入的聊天行。",
