	["Telling"] = "講述",
	["Tells you when a wishlist item is in a loot window or a roll, or drops in the dungeon you enter. It never loots or rolls for you."] = "當願望清單物品出現在拾取視窗或擲骰中，或在你進入的地城中掉落時提醒你。絕不會替你拾取或擲骰。",
	["Test alert"] = "測試提醒",
