	["That dungeon is not in the dungeon list."] = "該地城不在地城列表中。",
	["That goal could not be set."] = "無法設定該目標。",
	["That is not a journal code. Look for !EUJ1!, FJ2: or FJ1: at the start."] = "這不是日誌程式碼。請檢查開頭是否為!EUJ1!、FJ2:或FJ1:。",
