	["The %s page is switched off on the Loot Guide settings page."] = "%s頁面已在Loot Guide設定頁面中關閉。",
	["the address to report problems"] = "報告問題的地址",
	["The adventurer's log: plain past tense, places and levels first."] = "冒險者日誌：樸素的過去式，地點和等級在前。",
	["The Alts module stays off while %s is loaded, so only this character is known."] = "載入%s時角色模組保持關閉，因此只知道此角色。",
	["The Argent Dawn sends you to Naxxramas once you are Honored or better; each rank makes the way in cheaper."] = "銀色黎明會在你達到尊敬或更高時派你前往納克薩瑪斯；每提升一級，進入的代價就更低。",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on first."] = "進入資格標籤頁位於Loot Guide中。請先開啟Loot Guide。",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on to use it."] = "進入資格標籤頁位於Loot Guide中。開啟Loot Guide即可使用。",
	["The backup is merged into your journal."] = "備份已合併到你的日誌中。",
	["The best gear you can get for your spec and level, your filter and stat order, and two plan sets of your own."] = "符合你的專精和等級、篩選和屬性順序的可獲取最佳裝備，以及你自己的兩套計劃套裝。",
	["The best idea for right now and why it is here. A dungeon opens as a trip plan: the quests to pick up first, getting in, inside, and afterwards. Every button only shows you the way."] = "當下最好的建議及其理由。地城會以出行計劃開啟：先接哪些任務、如何進入、內部和之後。每個按鈕都只為你指路。",
	["The best item per slot from your list, what you wear, your two plan sets and your wishlist by slot. Click a slot to pick something else."] = "你的列表中每個部位的最佳物品、你身上的裝備、你的兩套計劃套裝和按部位排列的願望清單。點選一個部位來選擇別的物品。",
	["The best items on your list for your spec and the plan phase, one per slot. The number is the gain over what you wear."] = "符合你的專精和計劃階段的列表最佳物品，每個部位一件。數字是相對你身上裝備的收益。",
	["The card joins the suggestions again."] = "該卡片重新加入推薦。",
	["The cards you put away. They come back at your next level or after 24 hours."] = "你收起的卡片。它們會在你下一級或24小時後回來。",
	["The cards you sent off with Not now, with Bring back."] = "你用“以後再說”送走的卡片，附帶“恢復”。",
	["The cards you sent off with Not now."] = "你用“以後再說”送走的卡片。",
	["The chain as a chart: every step a box, lines to the steps that need it."] = "以圖表展示任務鏈：每一步一個方框，連線指向需要它的步驟。",
	["The check could not start."] = "無法開始檢查。",
	["The check is running: %d of %d quests asked. %s stops it."] = { other = "檢查進行中：已詢問%d/%d個任務。%s可停止。" },
	["The client does not know where this entrance is."] = "客戶端不知道這個入口在哪裡。",
	["The code is incomplete or damaged (%s). Copy all of it and paste it again."] = "程式碼不完整或已損壞（%s）。請完整複製後重新貼上。",
	["The code is incomplete or damaged. Copy all of it and paste it again."] = "程式碼不完整或已損壞。請完整複製後重新貼上。",
	["The commands and the address for problems. Pages, drop chances, the rating mode, alerts and the window look are in /eui > Loot Guide."] = "命令和問題反饋地址。頁面、掉落機率、評分模式、提醒和視窗外觀在/eui > Loot Guide中。",
	["The Crescent Key opens the doors of Dire Maul West and North; a boss in Dire Maul East drops it."] = "新月鑰匙可以開啟厄運之槌西區和北區的大門；厄運之槌東區的一個首領會掉落它。",
	["The data has no place on your map for this quest's giver."] = "資料中沒有此任務發布者在你地圖上的位置。",
	["The database needs the loot data"] = "資料庫需要掉落資料",
	["The Defilers"] = "汙染者",
