	["the details below"] = "檢視下方詳情",
	["The door opens at level %d."] = "大門在%d級時開啟。",
	["The drop data comes with the Loot Guide. Turn the Loot Guide on to use it."] = "掉落資料隨Loot Guide提供。開啟Loot Guide即可使用。",
	["The Drowned City"] = "The Drowned City",
