	["the dummy does not hit back"] = "訓練假人不會還手",
	["the dungeon"] = "該地城",
	["The EldoUI page and the place to report problems. Copy (Ctrl+C) and open them in your browser."] = "EldoUI頁面和問題反饋處。複製（Ctrl+C）後在瀏覽器中開啟。",
	["The EldoUI project page and the address to report a wrong drop or a problem, ready to copy."] = "EldoUI專案頁面和報告錯誤掉落或問題的地址，可直接複製。",
	["The entrance is %s."] = "入口%s。",
	["The Exodar"] = "艾克索達",
	["The export did not work. The error is in the error list."] = "匯出失敗。錯誤在錯誤列表中。",
	["The filters hide every answer."] = "篩選條件隱藏了所有結果。",
	["The first faction that counts you as Honored."] = "第一個視你為尊敬的陣營。",
	["The first flight path you learned."] = "你學會的第一條飛行路線。",
	["The first one on %s. Take its items or money from a mailbox."] = "最早的一封在%s到期。從郵箱取出其中的物品或金錢。",
