	["The first time you entered a dungeon."] = "你第一次進入地城。",
	["The first time you entered a raid."] = "你第一次進入團隊副本。",
	["The game could not save it. Try your own screenshot key."] = "遊戲無法儲存。請試試你自己的截圖按鍵。",
	["The game did not show your weapon skill, so the simulator used the usual skill for your level (5 per level)."] = "遊戲沒有顯示你的武器技能，因此模擬器使用了你等級的一般技能（每級 5 點）。",
	["The game does not list that faction for you yet. Check the spelling on your Reputation tab."] = "遊戲尚未為你列出該陣營。請在聲望標籤頁上核對拼寫。",
	["The game does not list this dungeon yet. It shows here as soon as it does."] = "遊戲尚未列出此地城。一旦列出就會顯示在這裡。",
	["The game does not report this step; it counts once the next one is done."] = "遊戲不會報告這一步；下一步完成時它就算完成。",
	["The game does not tell where this entrance is."] = "遊戲沒有提供這個入口的位置。",
	["The game has no map picture for this place. Here are its bosses in order; click one for its loot."] = "遊戲沒有此地點的地圖圖片。這裡按順序列出它的首領；點選一個檢視其掉落。",
	["The game has no name for that place yet."] = "遊戲中還沒有該地點的名稱。",
	["The game has not sent this item's stats yet."] = "遊戲尚未傳送此物品的屬性。",
	["the game marks it done"] = "遊戲將其標為已完成",
