	["the game remembers it as done"] = "遊戲記得它已完成",
	["The game shows this rare on your minimap right now."] = "遊戲現在正在你的小地圖上顯示這個稀有怪。",
	["The game's map could not place any creature camp. Open the world map once and come back."] = "遊戲地圖無法定位任何怪物營地。請開啟一次世界地圖後再回來。",
	["The game's map says you are in this zone."] = "遊戲地圖顯示你在此區域。",
	["The game's own count of quests you completed."] = "遊戲自身統計的已完成任務數。",
	["The game's own count of your deaths."] = "遊戲自身統計的死亡次數。",
	["The gear you wear; each slot shows how much its Best in Slot item adds."] = "你身上的裝備；每個部位顯示其Best in Slot物品能帶來的提升。",
	["The group finder could not open here."] = "無法在此處開啟隊伍查詢器。",
	["The group finder opens after combat."] = "隊伍查詢器會在戰鬥結束後開啟。",
	["The guide goes back to following your zone when your map changes."] = "地圖改變後，指南會重新跟隨你的地區。",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips."] = "推薦出行需要掉落資料（EldoUI_LootData插件）或遊戲的地城搜尋器列表。",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips. Quests in your log still show here."] = "推薦出行需要掉落資料（EldoUI_LootData插件）或遊戲的地城搜尋器列表。你日誌中的任務仍會顯示在這裡。",
	["The Hall of Thanes"] = "The Hall of Thanes",
	["The honor cost and PvP rank the item needs."] = "該物品需要的榮譽花費和PvP軍銜。",
	["The import is undone."] = "已撤銷匯入。",
	["The instance page with every boss, its quests and its trash loot."] = "副本頁面，包含每個首領、其任務和小怪掉落。",
	["The item; its color is its quality."] = "物品；顏色表示品質。",
	["the items that fit this slot"] = "適合此欄位的物品",
	["The items you see this boss drop are added here."] = "你看到此首領掉落的物品會加入此處。",
	["The journal as a readable document, by chapter, with goals, notes and quests. Companion names are left out."] = "按章節編排、可閱讀的文件形式日誌，包含目標、筆記和任務。不含同伴名字。",
	["The journal as a web page (HTML). Save it as a .html file, open it in a browser and print it to PDF. Opened outside the game it loads its fonts from Google Fonts."] = "網頁（HTML）形式的日誌。將它儲存為.html檔案，在瀏覽器中開啟並列印為PDF。在遊戲外開啟時會從Google Fonts載入字型。",
	["The journal as plain text, by chapter."] = "按章節編排的純文字日誌。",
	["The journal begins in %s"] = "日誌始於%s",
	["The journal has no company by that name."] = "日誌中沒有叫這個名字的同伴。",
	["The journal has not been here yet."] = "日誌還沒有到過這裡。",
	["The journal is not ready yet. Try again in a moment."] = "日誌尚未就緒。請稍後再試。",
	["The journal of %s, saved %s."] = "%s的日誌，儲存於%s。",
	["The journal shows what the game and your other EldoUI modules wrote down. Nothing is guessed."] = "日誌顯示遊戲和你的其他EldoUI模組記錄下的內容。沒有任何猜測。",
	["The journal waits for the end of combat"] = "日誌在等待戰鬥結束",
	["The Journal window's dark page and the EldoUI Book, the Storyteller detail with keepsakes, the tracker under your quests and moments in the alert lane."] = "日誌視窗的深色頁面和EldoUI書、帶紀念的講述者詳情、你任務下方的追蹤器以及提醒欄中的時刻。",
	["The Journal window's own dark page with the accent color."] = "日誌視窗自帶的帶強調色的深色頁面。",
	["The journal's own rows: short, exact, with digits."] = "日誌自己的行：簡短、準確、使用數字。",
	["The journal's pages are switched off or still loading."] = "日誌頁面已關閉或仍在載入。",
	["The Journey's day view on the day you last played."] = "你上次遊戲那天的旅程日檢視。",
	["The Key to the City opens the service gate of Stratholme; a boss inside drops it."] = "城市鑰匙可以開啟斯坦索姆的後門；裡面的一個首領會掉落它。",
	["The last one you had open"] = "你上次開啟的那個",
	["The last run is outdated: your level, gear, talents or list changed."] = "上次執行已過時：你的等級、裝備、天賦或列表已改變。",
	["The League of Arathor"] = "阿拉索聯軍",
	["The level log was off for these levels."] = "這些等級期間等級記錄處於關閉狀態。",
	["The level of the target dummy. Bosses are three levels above you: more misses, glancing blows and resists."] = "訓練假人的等級。首領比你高三級：未命中、偏斜和抵抗都會更多。",
	["The light part is rested experience: kills give double experience until it is used up."] = "淺色部分是休息經驗：在用完之前，擊殺獲得雙倍經驗。",
	["The line is in the chat box. Press Enter to send it, or Escape to drop it."] = "這行文字已在聊天框中。按Enter傳送，或按Esc放棄。",
	["The list on the left leaves out attunements you have finished."] = "左側列表不包含你已完成的進入資格。",
	["The long chain of Anachronos and the three dragonflights that opens the gates of Ahn'Qiraj."] = "阿納克洛斯和三條龍軍團的漫長任務鏈，它將開啟安其拉之門。",
	["The long chain through Stormwind and Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "這條穿過暴風城和黑石塔的漫長任務鏈，以進入奧妮克希亞的巢穴所需的龍火護符告終。",
	["the loot"] = "檢視掉落",
	["The loot data does not list where this recipe comes from."] = "掉落資料沒有列出這張配方的來源。",
	["The loot data has no place on your map for this."] = "掉落資料中沒有它在你地圖上的位置。",
	["The loot data has no rares or named creatures for the zone you are in. Pick a zone on the left."] = "掉落資料中沒有你所在區域的稀有怪或有名字的怪物。在左側選擇一個區域。",
	["The loot data lists no bosses here."] = "掉落資料沒有列出這裡的首領。",
	["The loot data lists no crafts for this profession."] = "掉落資料沒有列出此專業的製作物品。",
	["The loot data lists no factions for your side."] = "掉落資料中沒有你所在陣營的聲望陣營。",
	["The loot data lists no factions of the other side."] = "掉落資料中沒有對方陣營的聲望陣營。",
	["The loot data lists no rewards for this faction."] = "掉落資料沒有列出此陣營的獎勵。",
	["The loot data lists no vendors, quest rewards or drops for this event."] = "掉落資料沒有列出此節日的商人、任務獎勵或掉落。",
	["The Loot Guide opens out of combat."] = "Loot Guide會在脫離戰鬥後開啟。",
	["The Loot Guide stays off while %s is loaded."] = "載入%s時Loot Guide保持關閉。",
	["The lowest quality a find needs to be written on the Journey. Changing it on a preset turns it into Custom."] = "發現物需要達到的最低品質才會寫入旅程。在預設上更改它會變為自定義。",
	["The mouse wheel turns the pages too."] = "滑鼠滾輪也可以翻頁。",
	["The next open step of each attunement and key."] = "每個進入資格和鑰匙的下一個開放步驟。",
	["The next step's quest giver on the map and toasts as you go."] = "在地圖上標出下一步的任務發布者，並隨進度顯示通知。",
	["The Night ledger Book in smaller text, short chapters and a slim tracker. Row size stays the Loot Guide's own setting."] = "夜間賬簿書，文字更小、章節更短、追蹤器更窄。行高仍使用Loot Guide自己的設定。",
	["The numbers come from many short fights with random rolls. The ± range shows how sure they are (95 %)."] = "這些數字來自許多帶隨機判定的短時戰鬥。±範圍表示其可信度（95 %）。",
	["The oldest %d are kept as counts on their levels."] = { other = "最早的%d條只在其等級上保留為計數。" },
	["The oldest goes when a new one would pass this. The newest copy from before an EldoUI update has a slot of its own and is always kept."] = "新增一條會超出此數時，最早的一條會被移除。EldoUI 更新前最新的一份副本有自己的位置，始終保留。",
	["The order your spec values stats in. Drag to change it."] = "你的專精看重屬性的順序。拖動來更改。",
	["The page the window shows when you open it outside a dungeon. The gear holds a switch for each page and the Catalog's settings."] = "在地城外開啟視窗時顯示的頁面。齒輪中有每個頁面的開關和目錄的設定。",
	["the page you left, even inside a dungeon"] = "你上次離開的頁面，即使在地城中",
	["The pages of My Adventure on the Journal window's own dark panel, or on parchment with dark ink. The Book and the character card keep their own Book look."] = "我的冒險的頁面放在日誌視窗自帶的深色面板上，或放在深色墨水的羊皮紙上。書和角色卡片保留它們自己的書本外觀。",
	["The people you grouped with last first."] = "最近一起組隊的人在前。",
	["The people you met and grouped with."] = "你遇見並一起組隊的人。",
	["The people you spent the most time with first."] = "和你相處時間最長的人在前。",
	["The people you traveled with: time together and how it was spent, dungeons and quests together, and your notes on them."] = "和你一起旅行的人：在一起的時間和度過方式、一起的地城和任務，以及你對他們的筆記。",
	["The places you came to last first."] = "最近去過的地點在前。",
	["The places you spent the most time in first."] = "你待得最久的地點在前。",
	["The planner is already empty."] = "規劃已經是空的。",
	["The planner is empty."] = "已清空規劃。",
	["The PvP planner works out weeks from this. Leave 0 to use what you earned in recent weeks."] = "PvP規劃器據此計算週數。保持0則使用你最近幾周的獲得量。",
	["The quest chains come from EldoUI_LootData, which loads a few seconds after login."] = "任務鏈來自EldoUI_LootData，它在登入幾秒後載入。",
	["The quest giver is %s."] = "任務發布者%s。",
	["The quest giver's exclamation mark right of the bar, like the game's quest icon."] = "血條右側顯示任務發布者的感嘆號，與遊戲的任務圖示相同。",
	["The quest givers are %s."] = "任務發布者們%s。",
	["The quest tracker leaves room at its bottom for the journal tracker. With Questie, the journal tracker sits right under Questie's list."] = "任務追蹤器會在底部為日誌追蹤器留出空間。使用Questie時，日誌追蹤器緊貼在Questie列表下方。",
	["The quests for this instance with your status: open, done or locked."] = "此副本的任務和你的狀態：可接取、已完成或已鎖定。",
	["The quests you archived, with Restore."] = "你歸檔的任務，附帶“恢復”。",
	["The reminder stays and shows each time, instead of once."] = "提醒會保留並每次都顯示，而不是隻顯示一次。",
	["The reputation the item needs, red while you are below it."] = "該物品需要的聲望，在你未達到時顯示為紅色。",
	["The road is waiting. Every zone you visit gets a card."] = "道路在等待。你拜訪的每個區域都會獲得一張卡片。",
	["The role they had when they sent it."] = "他們傳送時擔任的職責。",
	["The same fights (same dice) for every set, so the differences are steadier than the totals."] = "每個套裝使用相同的戰鬥（相同的骰子），因此差值比總值更穩定。",
	["The Seal of Ascension opens the doors of Upper Blackrock Spire for your whole group."] = "晉升印章可為你的整個隊伍開啟黑石塔上層的大門。",
	["The search index is built out of combat. Try again in a moment."] = "搜尋索引會在脫離戰鬥後建立。請稍後再試。",
	["The search looks through the %s table."] = "搜尋範圍為%s表。",
	["The section My Adventure opens on: Today, a page you pick (Next trips, Journey, Book, Story so far, Keepsakes, Places, Quests, Fellowship, Goals or Notes), or the last one you had open."] = "我的冒險開啟時的分割槽：今天、你選擇的頁面（接下來的出行、旅程、書、迄今為止的故事、紀念、地點、任務、同伴、目標或筆記），或你上次開啟的那個。",
	["The section you came back from. Alt+Right does the same."] = "你從中返回的分割槽。Alt+右方向鍵效果相同。",
	["The section you had open before. Alt+Left or Backspace does the same."] = "你之前開啟的分割槽。Alt+左方向鍵或Backspace效果相同。",
	["The set an item is part of (owned of total) and what a token buys."] = "物品所屬的套裝（已擁有/總數）以及兌換物可換取的物品。",
	["The set bonuses show once the game has the pieces' details (hover a piece once)."] = "遊戲獲得各部件的詳情後才會顯示套裝獎勵（將滑鼠在部件上懸停一次）。",
	["The set is shared with the Best in Slot page. This can't be undone."] = "此套裝與Best in Slot頁面共用。此操作無法復原。",
	["The Shadowforge Key opens the gates deeper in Blackrock Depths."] = "暗爐鑰匙可以開啟黑石深淵更深處的大門。",
	["The Shapers Terrace"] = "The Shapers Terrace",
	["The simulation is done."] = "模擬完成。",
	["The simulator could not start."] = "模擬器無法啟動。",
	["The simulator folder EldoUI_LootSim is not installed. It comes with EldoUI: put it next to the EldoUI folder in Interface\\AddOns."] = "未安裝模擬器資料夾EldoUI_LootSim。它隨EldoUI一起提供：把它放在Interface\\AddOns中EldoUI資料夾旁邊。",
	["The simulator found no damage spells it can use yet."] = "模擬器還沒找到可用的傷害法術。",
	["The simulator has no model for your class."] = "模擬器沒有你的職業的模型。",
	["The simulator has no numbers for this item yet."] = "模擬器還沒有此物品的資料。",
	["The simulator has no stats for these items, so sets with them are not simulated: "] = "模擬器沒有這些物品的屬性，所以不會模擬含有它們的套裝： ",
	["The simulator runs out of combat. Try again when the fight is over."] = "模擬器在非戰鬥狀態下執行。戰鬥結束後再試。",
	["The Skeleton Key opens the gates of Scholomance."] = "骷髏鑰匙可以開啟通靈學院的大門。",
	["The sound that plays with a wishlist alert."] = "願望清單提醒時播放的聲音。",
	["The step is %s."] = "這一步%s。",
	["The step is ready to hand in."] = "這一步可以交付了。",
	["the story of this quest"] = "此任務的故事",
	["The suggestions again."] = "重新推薦。",
	["The tab lists attunements, keys and dungeon quests once the quest data is loaded."] = "任務資料載入後，此標籤頁會列出進入資格、鑰匙和地城任務。",
	["The tavern song: warm and vivid, never false."] = "酒館歌謠：溫暖生動，絕不虛假。",
	["The tour runs out of combat."] = "導覽在非戰鬥狀態下進行。",
	["The view the Overview button opens first."] = "總覽按鈕首先開啟的檢視。",
	["The Warlord's Command chain through Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "這條穿過黑石塔的督軍的命令任務鏈，以進入奧妮克希亞的巢穴所需的龍火護符告終。",
	["The whole Book in this tone as plain text, in a copy box."] = "以此語氣寫成的整本書，以純文字放在複製框中。",
	["The whole journal as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "整個日誌作為一段程式碼，可以儲存或貼上到另一臺電腦上。不會傳送到任何地方。",
	["The whole story in this tone as plain text, in a copy box."] = "以此語氣寫成的完整故事，以純文字放在複製框中。",
	["The whole story with headings, for a website, a forum, or Discord."] = "帶標題的完整故事，適用於網站、論壇或Discord。",
	["The window lets the game show through a little. How much: General > Panel opacity. Drag the window's corner grip to change its size."] = "視窗會略微透出遊戲畫面。程度：General > Panel opacity。拖動視窗角落的手柄可改變其大小。",
	["The zone is %d-%d; you are level %d."] = "該區域為%d-%d級；你的等級為%d。",
	["The zone list is built out of combat. It shows once the fight is over."] = "區域列表在非戰鬥狀態下生成。戰鬥結束後顯示。",
	["The Zones section lives in the Loot Guide. Turn the Loot Guide on to use it."] = "區域部分位於Loot Guide中。開啟Loot Guide即可使用。",
	["There is no import to undo."] = "沒有可撤銷的匯入。",
	["There is no journal to back up yet."] = "還沒有可備份的日誌。",
	["There is no journal to export yet."] = "還沒有可匯出的日誌。",
	["There is no live position inside dungeons."] = "地城內沒有實時位置。",
	["They come back at your next level or after 24 hours."] = "它們會在你下一級或24小時後回來。",
	["They may be in another character's fellowship."] = "他們可能在另一個角色的同伴中。",
	["They were level %s."] = "他們當時是%s級。",
	["Things you want to work towards. Their progress moves by itself as the game reports it."] = "你想努力達成的目標。其進度會隨遊戲報告自動推進。",
	["This backup is still being written. Try again in a moment."] = "此備份仍在寫入中。請稍後再試。",
	["This can't be undone."] = "此操作無法復原。",
	["This client"] = "此客戶端",
	["This client cannot set a map pin."] = "此客戶端無法設定地圖示記。",
	["This client has no group finder window."] = "此客戶端沒有隊伍查詢器視窗。",
	["This code contains only recent changes. Merge adds them to your journal and keeps your existing entries."] = "此程式碼僅包含近期更改。合併會將這些更改加入日誌，並保留現有項目。",
	["This game client cannot answer quest questions."] = "此遊戲客戶端無法回答任務查詢。",
	["This game client does not tell add-ons about poisons, oils and other temporary weapon enchants, so they are not counted."] = "此遊戲客戶端不會把毒藥、油和其他臨時武器附魔告知插件，因此不計入。",
	["This is how wishlist alerts look."] = "這就是願望清單提醒的樣子。",
	["this is not a Best in Slot string"] = "這不是Best in Slot字串",
	["this is not a wishlist string"] = "這不是願望清單字串",
	["This list is already empty."] = "此清單已經是空的。",
	["This list shows the factions you have met. Show all factions to see every faction's rewards."] = "此列表顯示你已接觸的陣營。點選顯示所有陣營可檢視每個陣營的獎勵。",
	["This page shows where to go next and what is waiting for you."] = "此頁面顯示接下來去哪裡，以及有什麼在等著你。",
	["This place cannot be shown on your map."] = "此地點無法在你的地圖上顯示。",
	["This place has no dungeon map."] = "此地點沒有地城地圖。",
	["This place has no point on your map yet."] = "此地點在你的地圖上還沒有位置點。",
	["This session"] = "本次登入",
	["Thorium Brotherhood"] = "瑟銀兄弟會",
	["Thunder Bluff"] = "雷霆崖",
	["check it off"] = "勾選",
	["check it off yourself"] = "自己勾選",
	["Checked sets run in the next Sets run, all in the same fights."] = "勾選的套裝會在下一次套裝模擬中執行，全部使用相同的戰鬥。",
	["Tier sets"] = "套裝（T系列）",
	["Timbermaw Hold"] = "木喉要塞",
	["Time"] = "時間",
	["time here"] = "停留時間",
	["Time here"] = "停留時間",
	["Time in the same group, away from keyboard not counted."] = "在同一隊伍中的時間，不計暫離。",
	["Time played at each level, from the level log."] = "每個等級的遊戲時間，來自等級記錄。",
	["Time together"] = "共處時間",
	["Time you spent here, away from keyboard not counted."] = "你在這裡度過的時間，不計暫離。",
	["to %s"] = "交給%s",
	["to %s, %s"] = "交給%s，%s",
