	["Backups are copies of this journal in your saved data. The game writes them to disk when you log out or /reload."] = "備份是此日誌在你已儲存資料中的副本。遊戲會在你登出或/reload時將其寫入磁碟。",
	["Backups of your runs"] = "你的副本記錄備份",
	["Classic: chances from Classic data; Forever may differ. Seen: what you looted yourself, with the number of kills (needs Mob and Loot Info)."] = "經典舊世：機率來自經典舊世資料；Forever可能不同。已見：你自己拾取的物品及擊殺數（需要怪物和拾取資訊）。",
	["Copy a runs code"] = "複製副本記錄程式碼",
	["Creatures that can drop an item that starts a quest get a tooltip line and a small icon on their nameplate."] = "可能掉落任務起始物品的生物會在滑鼠提示中多一行，並在姓名板上顯示一個小圖示。",
	["Delete this run?"] = "刪除這次副本記錄？",
	["Every dungeon and raid run stays in your journal with who was in it. Its own code keeps them safe or moves them to another PC."] = "每次地城和團隊副本都會連同同行的人一起保存在你的日誌中。它有自己的程式碼，可用來保管或轉移到另一臺電腦。",
	["Every zone's quests in the Loot Guide's Catalog: how many you have done, what is left and who gives them."] = "Loot Guide目錄中每個區域的任務：你已完成多少、還剩什麼以及由誰發布。",
	["Everyone passed"] = "所有人都放棄",
	["For this character: your stat weights (fast, the same as the Upgrades arrows), or the simulator (DPS against a target dummy, run when you press Sim)."] = "針對此角色：你的屬性權重（快速，與提升箭頭相同），或模擬器（對訓練假人的DPS，點選Sim時執行）。",
	["Forget"] = "忘記",
	["Forget this name?"] = "忘記這個名字？",
	["Green is done, the accent is in your quest log, yellow is available, gray is locked. An unreported step counts once the next is done."] = "綠色為已完成，強調色為在任務日誌中，黃色為可接，灰色為未解鎖。未回報的步驟在下一步完成後即算完成。",
	["Journal run backups of %s"] = "%s的日誌副本記錄備份",
	["Journal runs backup"] = "日誌副本記錄備份",
	["Journal runs of %s"] = "%s的日誌副本記錄",
	["Load the runs of %s (saved %s) into this character?"] = "將%s的副本記錄（儲存於%s）載入到此角色？",
	["Loads a runs code (!EUJR1!). You see what it holds, then Merge or Replace."] = "載入副本記錄程式碼（!EUJR1!）。你會先看到其內容，然後選擇合併或替換。",
	["Loot Guide in EldoUI %s. %s opens the window, %s the simulator, %s lists every command."] = "EldoUI %s中的Loot Guide。%s開啟視窗，%s開啟模擬器，%s列出所有指令。",
	["Merge adds the runs your journal is missing and never adds one twice. Replace puts your runs back exactly as they were then."] = "合併會新增你的日誌缺少的副本記錄，且絕不重複新增。替換會讓你的副本記錄完全恢復到當時的樣子。",
	["Need (off spec)"] = "需求(次要專精)",
	["No backup of your runs yet."] = "你的副本記錄尚無備份。",
	["No roll"] = "未擲骰",
	["Nothing to read. Paste a runs code first."] = "沒有可讀取的內容。請先貼上副本記錄程式碼。",
	["On a creature that can drop an item that starts a quest: the item, the quest and the drop chance, until you have the item or did the quest."] = "在可能掉落任務起始物品的生物上：物品、任務和掉落機率，直到你擁有該物品或完成該任務。",
	["Paste a runs code"] = "貼上副本記錄程式碼",
	["Paste a runs code from EldoUI (!EUJR1!). You see what it holds before anything changes."] = "貼上來自EldoUI的副本記錄程式碼（!EUJR1!）。在任何更改之前，你會先看到其內容。",
	["Pick a backup of your runs, then Merge or Replace. Your runs are backed up first."] = "選擇一個副本記錄備份，然後選擇合併或替換。你的副本記錄會先被備份。",
	["Press Ctrl+C to copy the code. Use \"Paste a runs code\" on this PC or another to restore your runs. Nothing is sent anywhere."] = "按Ctrl+C複製程式碼。在這臺或另一臺電腦上使用“貼上副本記錄程式碼”即可恢復你的副本記錄。不會傳送到任何地方。",
	["Restore your runs"] = "恢復你的副本記錄",
	["Restore your runs from %s?"] = "恢復%s的副本記錄？",
	["Runs code"] = "副本記錄程式碼",
	["Show %d earlier runs"] = { other = "顯示更早的%d次副本" },
	["Someone"] = "某人",
	["That is not a runs code. A runs code starts with !EUJR1!."] = "這不是副本記錄程式碼。副本記錄程式碼以!EUJR1!開頭。",
	["The name leaves every run and your companions; the runs and everyone else stay. Undo brings it back for 7 days."] = "該名字會從所有副本記錄和你的同伴中移除；副本記錄和其他人都會保留。撤銷可在7天內將其恢復。",
	["The run leaves your journal; everything else stays. Undo brings it back for 7 days."] = "這次副本記錄會從你的日誌中移除；其他一切都會保留。撤銷可在7天內將其恢復。",
	["The runs of %s, saved %s."] = "%s的副本記錄，儲存於%s。",
	["The tooltip line has its own switch on the Tooltip page. The chance follows the Loot Guide's Drop chances setting."] = "滑鼠提示行在滑鼠提示頁面有單獨的開關。機率依照Loot Guide的掉落機率設定。",
	["There are no runs to back up yet."] = "還沒有可備份的副本記錄。",
	["This can be done out of combat only."] = "你無法在戰鬥中執行那個動作",
	["Transmog"] = "塑形",
	["Updating the list of runs. It fills in by itself in a moment."] = "正在更新副本記錄清單。稍後會自動填入。",
	["What the pages show; everything is always written down. Essentials: levels, deaths, notes, goals. Storyteller: adds spells, professions and places. Chronicler: everything."] = "頁面顯示的內容；所有內容總會被記下。要點：等級、死亡、備註、目標。講述者：增加法術、專業和地點。編年史家：全部。",
	["with %s others"] = { other = "與其他%s人" },
	["Won with you"] = "與你一起贏得",
	["Your character's journal in the Journal window: a diary that writes itself, keepsakes, places, quests, goals and notes, your story from 1 to 60 and where to go next."] = "日誌視窗中你角色的日誌：一本自動書寫的日記，包含紀念、地點、任務、目標和備註，你從1級到60級的故事以及接下來去哪裡。",
	["Your runs are back as they were then."] = "你的副本記錄已恢復到當時的樣子。",
	["Your runs as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "你的所有副本記錄作為一段程式碼，可以儲存或貼上到另一臺電腦上。不會傳送到任何地方。",
	["Your runs as they are now are backed up first either way."] = "無論如何都會先備份你當前的副本記錄。",
} end)
